    const empty = '<section class="panel stack-sm" data-od-id="owner-empty"><h2>Пока нет опубликованных объектов</h2><p class="muted" style="margin:0;font-size:14px">Компонент или сетап создаётся и синхронизируется через CLI. Веб-интерфейс не редактирует состав объектов.</p><div class="row"><code class="codebox" style="flex:1">ai-stp component sync ./my-component</code><button class="btn btn-secondary" data-action="copy" data-copy="ai-stp component sync ./my-component">Copy</button></div><a href="#" class="muted" style="font-size:13px;text-decoration:underline" data-nav="docs">Документация по CLI</a></section>';
    return '<div class="stack" data-od-id="page-account"><div class="row" style="justify-content:space-between"><div><h1>Аккаунт</h1><p class="mono muted" style="font-size:12px;margin:6px 0 0">' + FIX.account + '</p></div><div class="row"><button class="btn btn-outline btn-sm" data-nav="publisher" data-id="' + FIX.account + '">Открыть публичную страницу</button><button class="btn btn-outline btn-sm" data-nav="profile-preview">Предпросмотр</button><button class="btn btn-outline btn-sm" data-nav="profile">Редактировать</button></div></div>' + (state.ownerEmpty ? empty : '<section class="stack-sm"><div class="row" style="justify-content:space-between"><h2>Мои объекты</h2><button class="back" data-action="toggle-empty">Показать пустое состояние</button></div><div class="grid-2">' + myComponents.map((x) => objectCard(x, "component")).join("") + mySetups.map((x) => objectCard(x, "setup")).join("") + "</div></section>") + '<section class="stack-sm"><h2>Привязанные идентичности</h2><div class="list-item"><div class="row">' + chip("google", "chip-soft") + '<span class="mono muted" style="font-size:12px">' + FIX.ts + '</span></div><button class="btn btn-outline btn-sm" disabled>Отвязать</button></div></section></div>';
